L33_1.m_Talk_JPN = "\227\129\159\227\129\182\227\130\147\226\128\166\226\128\166\227\129\147\227\130\147\227\129\170\230\132\159\227\129\152\227\129\16720\229\185\180\227\129\143\227\130\137\227\129\132\231\181\140\227\129\166\227\129\176\227\128\129\228\189\149\227\129\174\229\191\131\233\133\141\227\130\130\227\129\170\227\129\139\227\129\163\227\129\159\229\133\131\227\129\174\231\148\159\230\180\187\227\129\171\230\136\187\227\130\140\227\130\139\227\130\147\227\129\152\227\130\131\227\129\170\227\129\132\227\129\163\227\129\153\227\129\139\227\129\173\227\128\130"
