L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "\227\129\160\227\129\140\227\128\129\227\129\157\227\130\140\227\129\175\233\150\147\233\129\149\227\129\163\227\129\166\227\129\132\227\129\159\227\128\130\230\173\163\227\129\153\227\129\185\227\129\141\227\129\175\233\129\142\229\142\187\227\129\167\227\129\175\227\129\170\227\129\143\227\128\129\230\159\144\227\129\174\228\185\177\227\130\140\227\129\159\229\191\131\227\129\160\227\129\163\227\129\159\227\130\134\227\129\136\227\128\130"
