L7_1 = "\232\130\137\228\189\147\227\129\175\229\174\136\227\130\140\227\129\170\227\129\139\227\129\163\227\129\159\227\129\140\227\128\129\229\164\154\227\129\143\227\129\174\232\128\133\227\129\174\229\188\155\227\129\190\227\129\172\229\138\170\229\138\155\227\129\171\227\130\136\227\130\138\228\187\138\230\151\165\227\130\146\231\148\159\227\129\141\227\130\139\230\169\159\228\188\154\227\130\146\228\184\142\227\129\136\227\130\137\227\130\140\227\129\159\227\129\174\227\129\160\227\128\130"
